import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('el-engano-ii', 'B',
 [dict(t=1289, e=1345, titulo='La persona endurecida', txt='«No sea que alguno de vosotros sea endurecido». ¿Cómo es una persona endurecida? Sin temor a Dios, dice el hermano. […] Una persona que no es sensible, no tiene misericordia con los demás, y él quiere que lo traten bien, pero él trata mal a los demás.'),
  dict(t=3600, e=3650, titulo='Creerle a Dios', txt='«No sea que en alguno de vosotros haya un corazón malo de incredulidad». ¿Cómo puede empezar un corazón malo? No creyendo, hermano. Si usted le cree a Dios, le van a empezar a salir bien las cosas. […] A un corazón incrédulo le va a empezar a entrar la maldad para apartarse del Dios vivo. Quiere decir que aquí la base para que nosotros podamos seguir adelante es creerle a Dios. ¿Cuántos le creen a Dios?'),
  dict(t=4146, e=4205, titulo='Despojarse del hombre viejo', txt='«En cuanto a vuestra anterior manera de vivir, os despojéis del viejo hombre». El viejo hombre nos engaña, hermano, «que se corrompe según los deseos engañosos, y que seáis renovados en el espíritu de vuestra mente». Cuando usted es renovado en el espíritu de la mente del Señor, el hombre viejo se va muriendo y usted lo va matando, porque el hombre nuevo se va rejuveneciendo, rejuveneciendo, hasta que usted desintegra el hombre viejo.')],
 [dict(t=1500, txt='Hay gente que cree que está bien, pero bien mal, hermano, que está metida en un pecado mortal y no hay ningún problema.'),
  dict(t=2702, txt='Exhorte a sus hijos para que sean mejores, para que un día que ustedes no estén se defiendan.'),
  dict(t=4325, txt='Señor, he pasado por cosas terribles, pero ahora estoy entendiendo que tú tienes un plan donde solo entra tu verdad, donde todo engaño se tiene que ir de mi vida.')],
 ['¿En qué área de tu vida notas que el corazón se está endureciendo, y qué haría falta para ablandarlo esta semana?',
  'Si el hombre viejo nos engaña con deseos engañosos, ¿cuál es hoy el que más te engaña y cómo lo vas a renovar con la Palabra?',
  '¿Qué significa, en lo práctico, creerle a Dios esta semana?'])
